        "HỆ THỐNG TỰ ĐỘNG: ĐANG HOẠT ĐỘNG": { en: "AUTO SYSTEM: RUNNING", zh: "自动系统: 正在运行" },
        "HỆ THỐNG TỰ ĐỘNG: ĐÃ TẠM DÙNG": { en: "AUTO SYSTEM: PAUSED", zh: "自动系统: 已暂停" },
        "HỆ THỐNG TỰ ĐỘNG: ĐÃ TẠM DỪNG": { en: "AUTO SYSTEM: PAUSED", zh: "自动系统: 已暂停" },
        "Hệ thống hoạt động hoàn hảo! Không có sự cố nào để cảnh báo.": { en: "System is running perfectly! No issues to report.", zh: "系统运行状态完美！未检测到任何异常警报。" },
        "Hệ thống sẽ chạy ngầm kiểm tra XML RSS của YouTube mỗi chu kỳ được chọn. Thay đổi có hiệu lực ngay lập tức.": { en: "The system will run in the background to check the XML YouTube RSS each cycle is selected. Changes take effect immediately.", zh: "系统将在后台运行以检查XML YouTube RSS 每个周期都被选择。更改立即生效。" },
        "Hệ thống sẽ ngừng theo dõi và quản lý profile này.": { en: "The system will stop monitoring and managing this profile.", zh: "系统将停止监控和管理该浏览器环境。" },
        "Hệ thống sẽ nạp trực tiếp tất cả file video (.mp4, .mov, .mkv) trong thư mục này vào quy trình Render & Đăng mà không cần tải từ mạng.": { en: "The system will directly ingest all video files (.mp4, .mov, .mkv) in this directory into the Render & Post pipeline without downloading.", zh: "系统将直接导入该目录中的所有视频文件（.mp4、.mov、.mkv）进入渲染与发布流程，无需通过网络下载。" },
        "Hệ thống sẽ tự động xuất đồng thời cả 3 góc:": { en: "The system will automatically export all 3 corners simultaneously:", zh: "系统将自动同时导出所有 3 个角：" },
        "Hệ thống sẽ tự động đổi tên thư mục thực tế trong": { en: "The system will automatically dynamically rename the actual folder in", zh: "系统会自动 动态重命名实际文件夹" },
        "Hệ thống sẽ xóa bộ nhớ chống trùng lặp và các file video cũ của kênh này, cho phép bạn quét và tải lại các video từ đầu.": { en: "The system clears deduplication records and old videos for this channel, allowing you to rescan and download fresh videos from scratch.", zh: "系统将清空该频道的排重记录与历史下载文件，允许您重新扫描并从头下载视频。" },
        "Hệ thống tự động hóa khai thác YouTube sang TikTok Beta": { en: "Automated system exploiting YouTube content for TikTok Beta", zh: "全自动 YouTube 搬运转化与 TikTok Beta 创作者收益系统" },
        "Hệ thống tự động phát hiện in Lịch Scan Định Kỳ (hoặc when bấm quét): Tự động bắn thông báo when accounts ở trạng thái Monitoring chạm mốc 10.000 Followers.": { en: "Automatically detected during scheduled scans (or manual scans): Dispatches instant Telegram alerts when tracked accounts reach 10,000 followers.", zh: "定时巡检（或手动扫描）时自动检测：当关注中的账号达到万粉里程碑时立即推送通知。" },
        "Hệ thống tự động phát hiện trong": { en: "The system automatically detects in", zh: "系统自动检测到" },
        "Hệ thống tự động phát hiện trong Lịch Quét Định Kỳ (hoặc khi bấm quét): Tự động bắn thông báo khi tài khoản ở trạng thái 🔔 Đang theo dõi chạm mốc 10.000 Followers.": { en: "Automatically detected during scheduled scans (or manual scans): Dispatches instant Telegram alerts when tracked accounts reach 10,000 followers.", zh: "定时巡检（或手动扫描）时自动检测：当关注中的账号达到万粉里程碑时立即推送通知。" },
        "Hệ thống đang theo dõi tăng trưởng các tài khoản TikTok. Khi có tài khoản đạt mốc 10.000 Followers (đủ điều kiện tham gia TikTok Creator Rewards), thông tin tài khoản sẽ hiển thị tại đây và hệ thống sẽ tự động gửi thông báo qua Telegram.": { en: "The system monitors TikTok account growth. When an account reaches 10,000 Followers (eligible for TikTok Creator Rewards), account info appears here and automated alerts are sent via Telegram.", zh: "系统正在监控 TikTok 矩阵账号的粉丝增长。当有账号达到 10,000 粉丝（符合 TikTok 创作者基金资格）时，账号信息将在此展示，系统并通过 Telegram 自动发送通知。" },
