        "Katja (Nữ - Thời sự, tin tức rõ ràng)": { en: "Katja (Female - Current events, clear news)", zh: "Katja（女 - 时事、清晰新闻）" },
        "Keita (Nam - Thần thoại, anime, giật gân)": { en: "Keita (Male - Mythology, anime, thriller)", zh: "凯塔（男 - 神话、动漫、惊悚片）" },
        "Key Lỗi": { en: "Invalid Key", zh: "无效密钥" },
        "Khi có người xem comment, AI sẽ phản hồi thông minh, hóm hỉnh theo phong cách của kênh để kéo dài chuỗi thảo luận.": { en: "When viewers comment, AI generates smart, witty replies matching the channel style to lengthen comment discussion threads.", zh: "当有观众发表评论时，AI 将根据频道人设风格智能、幽默地进行回复，从而延长评论互动链条。" },
        "Khi có video mới, hệ thống tự động tải về thư mục chỉ định, cắt part và render 9:16 + phụ đề AI.": { en: "When a new video drops, the system downloads it, cuts parts, and renders 9:16 with AI captions.", zh: "当有新视频发布时，系统会自动下载至指定目录，切片并渲染为 9:16 竖屏 + AI 智能字幕。" },
        "Khi phát hiện nick đạt đủ 10.000 Follower, hệ thống sẽ gửi tin nhắn Telegram tới tất cả các kênh đang kích hoạt.": { en: "When it detects that the account has reached 10,000 Followers, the system will send it Telegram messages to all active channels.", zh: "当检测到账号达到10000粉丝时，系统会发送 向所有活动频道发送电报消息。" },
        "Khi phát hiện video mới qua RSS, tự động tải MP4 về thư mục.": { en: "When a new video is detected via RSS, it automatically downloads the MP4 to the folder.", zh: "当通过 RSS 检测到新视频时，它会自动将 MP4 下载到该文件夹​​。" },
        "Khi ổ cứng còn dưới 10 GB (Khuyên Dùng)": { en: "When free space is below 10 GB (Recommended)", zh: "当剩余磁盘空间少于 10 GB 时（推荐）" },
        "Khi ổ cứng còn dưới 20 GB": { en: "When free space is below 20 GB", zh: "当剩余磁盘空间少于 20 GB 时" },
        "Khi ổ cứng còn dưới 5 GB": { en: "When free space is below 5 GB", zh: "当剩余磁盘空间少于 5 GB 时" },
