        "Khoảng cách giữa các lần quét:": { en: "Interval between scans:", zh: "扫描间隔：" },
        "Khoảng cách giữa các lần đăng phải từ 10 đến 86400 giây!": { en: "The interval between postings must be from 10 to 86400 seconds!", zh: "发布之间的间隔必须为 10 到 86400 秒！" },
        "Khoảng cách ngày tùy chỉnh...": { en: "Custom date spacing...", zh: "自定义日期间距..." },
        "Khoảng cách tối thiểu giữa 2 bài:": { en: "Minimum distance between 2 posts:", zh: "2 个柱子之间的最小距离：" },
        "Khoảng cách tối thiểu giữa 2 lần đăng bài trên cùng 1 tài khoản TikTok. Nếu chiến dịch không chỉ định riêng, hệ thống sẽ tự động dùng mốc toàn cục này.": { en: "Minimum interval between 2 uploads on the same TikTok account. If the campaign does not specify its own interval, this global setting is applied.", zh: "同一 TikTok 账号两次发布之间的最小间隔时间。若活动未单独指定，系统将自动采用此全局设置。" },
        "Khoảng thời gian chờ trước lần thử kế tiếp (ví dụ: 15 phút).": { en: "Waiting period before next attempt (e.g. 15 minutes).", zh: "下次尝试之前的等待时间（例如 15 分钟）。" },
