        "Khuyến nghị: 10% - 15% để giọng nói luôn rõ nét.": { en: "Recommendation: 10% - 15% to keep voice clear.", zh: "建议：10% - 15% 以保持语音清晰。" },
        "Khuyến nghị: 10% - 15% để giọng nói/thuyết minh luôn rõ nét.": { en: "Recommended: 10% - 15% so voiceovers remain crisp and audible.", zh: "建议设置: 10% - 15%，以确保人声旁白清晰突出。" },
