        "Mỗi chiến dịch kết nối: Kênh YouTube - Mẫu Edit - Dàn Nick nhận bài": { en: "Each campaign links: YouTube Channel — Edit Formula — Target TikTok Accounts", zh: "每个活动连接: YouTube 来源频道 — 剪辑模板 — 接收视频的矩阵账号群" },
        "Mỗi chiến dịch kết nối: Kênh YouTube — Mẫu Edit — Dàn Nick nhận bài": { en: "Each campaign connects: YouTube Channel — Edit Template — Account Pool", zh: "每个活动连接: YouTube 来源频道 — 剪辑模板 — 矩阵账号池" },
        "Mỗi chiến dịch kết nối: Kênh YouTube → Mẫu Edit → Dàn Nick nhận bài": { en: "Each campaign connects: YouTube Channel → Edit Template → Account Pool", zh: "每个活动连接: YouTube 来源频道 → 剪辑模板 → 矩阵账号池" },
        "Mỗi clip xuất ra sẽ tự động bốc ngẫu nhiên 1 bài hát trong playlist này.": { en: "Each exported clip will automatically draw 1 song from this playlist at random.", zh: "每个导出的剪辑将自动从该播放列表中随机抽取 1 首歌曲。" },
        "Mỗi clip xuất ra sẽ tự động bốc ngẫu nhiên 1 bài hát trong thư mục này.": { en: "Each exported clip will automatically draw a random song from this folder.", zh: "每个导出的剪辑都会自动从此文件夹中随机绘制一首歌曲。" },
        "Mỗi key miễn phí 10,000 units/ngày. Thêm nhiều key để tự động xoay vòng khi hết quota. Phân cách bằng dấu phẩy hoặc xuống dòng.": { en: "Each free key provides 10,000 units/day. Add multiple keys for auto-rotation when quota is exhausted. Delimit with commas or newlines.", zh: "每个免费密钥每天提供 10,000 单位配额。添加多个密钥可在耗尽时自动轮换。以英文逗号或换行分隔。" },
        "Mỗi key trên 1 dòng hoặc cách nhau bằng dấu phẩy. Hệ thống sẽ tự động xoay sang key tiếp theo khi key hiện tại hết quota.": { en: "One key per line or comma-separated. The system will auto-switch to the next key when current quota expires.", zh: "每行一个密钥或用逗号分隔。当当前密钥耗尽配额时，系统将自动轮换至下一个可用密钥。" },
        "Mỗi mã key được liên kết cố định với máy tính này (theo HWID). Khách hàng có thể đổi máy bằng cách liên hệ Admin để Reset HWID.": { en: "Each license key is tied to this computer (via HWID). You can request a machine change by contacting Admin for HWID reset.", zh: "每个授权码与本机硬件码 (HWID) 绑定。如需更换电脑，请联系管理员重置 HWID。" },
