        "Mỗi video dài sẽ được cắt thành tối đa N đoạn ngắn": { en: "Each long video will be cut into a maximum of N short segments", zh: "每个长视频最多会被切割成N个短片段" },
        "Mỗi video từ kênh này sẽ tự động xuất 3 biến thể độc lập (VarA: Tò Mò, VarB: Tranh Luận, VarC: Cao Trào) kèm 3 bản nhạc BGM khác nhau để rải đều qua các nick TikTok.": { en: "Each video from this channel will automatically produce 3 independent variants (VarA: Curiosity, VarB: Controversy, VarC: Climax) with 3 different BGM tracks to distribute across TikTok accounts.", zh: "该频道的每个视频将自动生成3个独立变体（变体A: 好奇心，变体B: 争议讨论，变体C: 情绪高潮），搭配3首不同背景音乐均衡分发至矩阵账号。" },
