        "Tự động chọn GPMLogin / GenLogin": { en: "Auto Select GPMLogin / GenLogin", zh: "自动选择 GPMLogin / GenLogin" },
        "Tự động cuộn khi có log mới": { en: "Auto-scroll on new log entries", zh: "新日志产生时自动滚屏" },
        "Tự động cân bằng volume nhạc nền với giọng đọc video": { en: "Tu dong can bang volume nhac nen voi giong doc video", zh: "自动平衡背景音乐音量和视频语音" },
        "Tự động cắt PART theo mẫu Edit.": { en: "Automatically splits into PARTs per edit template.", zh: "根据剪辑模板自动进行多分集 PART 切片。" },
        "Tự động giải phóng profile và phục hồi các task bị dở dang (processing) khi khởi động lại máy hoặc treo quá thời gian cho phép.": { en: "Automatically releases profiles and recovers stuck tasks (processing) upon machine restart or when execution exceeds timeouts.", zh: "在电脑重启或任务超时挂起时，系统会自动释放浏览器环境并恢复未完成的中断任务。" },
        "Tự động giải phóng profile và phục hồi các task bị dở dang khi khởi động lại máy hoặc treo quá thời gian cho phép.": { en: "Auto-releases profiles and recovers stuck tasks when restarting or when timeout threshold is exceeded.", zh: "在系统重启或任务超时卡死时，自动释放环境资源并恢复未完成任务。" },
        "Tự động gom video tải về và video render vào thư mục con theo tên từng kênh": { en: "Tu dong gom video tai ve va video render vao thu muc con theo ten tung kenh", zh: "根据每个频道名称自动收集下载的视频和渲染的视频到子文件夹中" },
        "Tự động gắn thẻ #Shorts": { en: "Tu dong gan the #Shorts", zh: "Tu dong gan the #Shorts" },
        "Tự động khởi động ngầm khi bật máy tính và thu nhỏ xuống khay hệ thống.": { en: "Automatically launches silently when computer starts and minimizes to system tray.", zh: "开机时静默后台自动启动，并最小化至 Windows 系统托盘。" },
        "Tự động kéo MP4 chất lượng cao về máy khi phát hiện video mới qua RSS": { en: "Tu dong keo MP4 chat luong cao ve may khi phat hien video moi qua RSS", zh: "Tu dong keo MP4 chat luong cao ve may khi phat hien video moi qua RSS" },
        "Tự động kéo MP4 vào hàng đợi": { en: "Auto pull MP4 into queue", zh: "自动拉取 MP4 进入队列" },
        "Tự động kéo video mới từ RSS về máy tính": { en: "Automatically pull new videos from RSS feeds to disk", zh: "自动将 RSS 源中的新视频下载保存至本地" },
        "Tự động lấy video & render video từ kênh này.": { en: "Tu dong lay video & render video tu kenh nay.", zh: "自动从该频道抓取视频并渲染视频。" },
        "Tự động lật hình, đổi tốc độ và cắt chuẩn TikTok 9:16 ngay khi tải xong.": { en: "Tu dong lat hinh, doi toc do va cat chuan TikTok 9:16 ngay khi tai xong.", zh: "下载后立即自动翻转图像、更改速度并裁剪为 TikTok 标准 9:16。" },
        "Tự động quét RSS định kỳ mỗi 15 phút, tải video mới nhất và đưa vào pipeline Render AI": { en: "Auto-scans RSS every 15 minutes, downloads the newest video, and queues for AI rendering", zh: "每 15 分钟自动扫描 RSS 源，下载最新发布的视频并推入 AI 渲染流水线" },
        "Tự động render 1 video trọn vẹn nguyên bản, không cắt Part và không đóng dấu chữ PART.": { en: "Renders a complete single video without splitting parts or adding PART watermarks.", zh: "完整渲染单条视频，不进行分段切片，且画面中不添加 PART 分集标记。" },
        "Tự động xóa các file MP4 vật lý sau khi video đã được đăng thành công lên TikTok để giải phóng ổ cứng. Bản ghi database, lịch sử và chống trùng lặp được giữ nguyên vĩnh viễn.": { en: "Auto-delete physical MP4 files after successful TikTok publishing to free disk space. Database records, history, and duplicate prevention are permanently preserved.", zh: "视频成功发布到 TikTok 后自动删除本地物理 MP4 文件以释放磁盘空间。数据库记录、历史记录与防重数据永久保留。" },
        "Tự động xếp lịch thử lại khi gặp lỗi tạm thời (mạng, proxy, browser timeout, kết nối GPM). An toàn: không thử lại khi vi phạm, captcha hoặc văng phiên.": { en: "Automatically schedules retries on transient errors (network, proxy, browser timeout, GPM disconnection). Safe: does not retry on policy violations, captcha, or expired sessions.", zh: "遇到临时错误（网络、代理、浏览器超时、环境断开）时自动安排重试。安全机制：遇到违规封禁、人机验证或会话失效时不会盲目重试。" },
        "Tự động đồng bộ với tài khoản ElevenLabs của bạn. Giọng đọc sẽ tự động lách bản quyền audio cho video xuất bản. Để thay đổi API Key, vui lòng truy cập mục": { en: "Automatically synchronizes with your ElevenLabs account. Voiceovers bypass audio copyright on export. To update your API Key, please go to", zh: "自动与您的 ElevenLabs 账户同步。配音可在导出时规避音频版权风险。如需更换 API 密钥，请前往" },
        "Tự động đồng bộ với tài khoản ElevenLabs của bạn. Giọng đọc sẽ tự động lách bản quyền audio cho video xuất bản. Để thay đổi API Key, vui lòng truy cập mục Cài Đặt.": { en: "Auto-syncs with your ElevenLabs account. Voiceover bypasses copyright for exported videos. To change API Key, visit Settings.", zh: "自动同步您的 ElevenLabs 账户。配音可有效规避音频版权风险。如需更换 API Key，请前往设置页面。" },
