        "Định hướng AI cắt video và tạo câu mở đầu giật gân theo tâm lý người xem TikTok để tối đa tỷ lệ giữ chân & Viral.": { en: "Directs AI to cut videos and craft punchy opening hooks based on viewer psychology to maximize retention and virality.", zh: "引导 AI 智能剪辑并生成极具冲击力的开头黄金抓手，最大化观众完播留存率与上热门概率。" },
        "Định hướng AI cắt video và tạo câu mở đầu giật gân theo tâm lý người xem TikTok để tối đa tỷ lệ giữ chân (Retention) & Viral.": { en: "Guides AI to clip segments and create viral opening hooks tailored to TikTok viewer psychology for maximum retention and viral reach.", zh: "引导 AI 智能剪辑切片，并根据 TikTok 用户心理生成高爆黄金前3秒开头，最大化完播留存率与上热门几率。" },
        "Đọc trực tiếp cookie từ ổ đĩa và gọi API TikTok thần tốc (~0.5s/nick), không tốn RAM và không mở cửa sổ trình duyệt. Chỉ mở app/trình duyệt làm dự phòng khi cookie hết hạn.": { en: "Reads cookies directly from disk and calls the TikTok API instantly (~0.5s/account), using zero RAM without opening browser windows. Browsers only launch as a backup if cookies expire.", zh: "直接从磁盘读取 Cookie 并极速调用 TikTok API（约0.5秒/账号），不占用内存且无需打开浏览器窗口。仅在 Cookie 过期时才启动浏览器作为备用。" },
